# Layout · Due Diligence as the core & shell layout (Ritika, 10 Nov: "furniture and partitions should not be there, only empty bare
# shell"; then her core & shell drawing as the reference).
# s-layout-dd (regenerated by gen_floorflow.py each run) switches the plan to its shell layers once the plan is built (plan.planBare,
# app.js; PlanCanvas.bare, plan-canvas.js) and back when it leaves; while bare, the fit-out's SVG layers (room hover and names, the
# furniture cut-outs, the room and neighbourhood fills and numbers) are hidden, and the due diligence is drawn as the core & shell
# drawing draws it: the cores filled flat (lift lobbies light grey, fire exit stairs dark grey, washrooms pale blue, AHU grey-blue), the
# slabs to strengthen green and hatched, the external glazing a cyan line round the façade, the entries red.
# Only with window.ACKO_WOW. run after gen_floorflow.py, wow_sundd.py
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from eol import rd, wr
os.chdir(sys.argv[1])
def sub1(s, a, b, what):
    assert s.count(a) == 1, (what, s.count(a)); return s.replace(a, b)

# the external glazing, in the plan's mm (the slab edge, A-FLOR, read against the core & shell drawing): the whole façade but the north
# edge where the cores sit on it, wrapping round the two voids on the south (the west one with its neighbour, as the drawing does)
GLAZE = ("M59600 15100L14322 15100L41500 48400L77500 48400L77500 38800L103400 38800L103400 48400L171900 48400L171900 38800L184400 38800"
         "L184400 48400L253900 48400L253900 15100L224700 15100M215300 15100L197600 15100M153600 15100L103700 15100")

p = "slides/s-layout-dd.html"; s, nl = rd(p)
if "ddShell" not in s:
    s = sub1(s, "later(() => { arriving = false; build(sc); self.step(pend || 1, sc);",
                "later(() => { arriving = false; build(sc); ddShell(true); self.step(pend || 1, sc);", "arrive")
    s = sub1(s, "      } else build(sc);\n", "      } else { build(sc); ddShell(true); }   // the bare shell (10 Nov)\n", "enter")
    s = sub1(s, "      plan.planOff(); if (sc) sunDD(sc, false);\n",
                "      plan.planOff(); if (sc) sunDD(sc, false);\n      ddShell(false);                                   // the fit-out back for the slides after\n", "leave")
    s = sub1(s, "  function build(sc) {\n",
'''  // the core & shell drawing (10 Nov, the re-ordered deck): the plan bare, the glazing drawn round the façade, the slabs' hatch
  function ddShell(on) {
    if (!plan.planBare) return;
    if (!on) { plan.planBare(false); return; }
    if (!window.ACKO_WOW) return;
    plan.planBare(true);
    const dp = plan.deckPlan(), root = dp.root;
    if (!root.querySelector(".dd-glaze")) dp.ph.addLayer("dd-glaze", '<path d="''' + GLAZE + '''"/>');
    const dd = root.querySelector(".pl-dd");
    if (dd && !dd.querySelector("#dd-hatch")) dd.insertAdjacentHTML("afterbegin", '<defs><pattern id="dd-hatch" width="900" height="900" patternUnits="userSpaceOnUse"><path d="M0 0L900 900M900 0L0 900" stroke="#3a9a46" stroke-width="70" fill="none"/></pattern></defs>');
  }
  function build(sc) {
''', "fn")
    # the cards' swatches in the drawing's colours
    for a, b in ((('["stair", "Fire exit staircases", "#980000", "rgba(152,0,0,.22)"]'), '["stair", "Fire exit staircases", "#6f6f6f", "#8e8e8e"]'),
                 (('["ahu", "AHU rooms", "#1c64b4", "rgba(28,100,180,.2)"]'), '["ahu", "AHU rooms", "#8fb3cc", "#b5d1e4"]'),
                 (('["wash", "Washrooms", "#2f8f9d", "rgba(47,143,157,.2)"]'), '["wash", "Washrooms", "#a9c4e8", "#cfe0f6"]'),
                 (('["slab", "Slab to be strengthened", "#5222d0", "rgba(82,34,208,.16)"]'), '["slab", "Slab to be strengthened", "#3a9a46", "repeating-linear-gradient(45deg, #3a9a46 0 1px, #fff 1px 4px)"]'),
                 (('["lift", "Lift lobbies", "#c98a1a", "rgba(201,138,26,.22)"]'), '["lift", "Lift lobbies", "#9a9a9a", "#cfcfcf"]')):
        s = sub1(s, a, b, a[:12])
    s = sub1(s, '${k === "slab" ? "border-style:dashed" : ""}', "", "slab dash")
    # the two marks the cards don't cover
    s = sub1(s, "<b>Hover one</b> to find it on the floor.</p></div>",
                '<b>Hover one</b> to find it on the floor.</p><p class="dd-key"><span><i class="g"></i>External glazing</span><span><i class="e"></i>Entry ×2</span></p></div>', "key")
    s = sub1(s, "</style>",
        "/* the bare shell (10 Nov): no fit-out over the plan's shell, only the due diligence's own marks */\n"
        "#world-plan.bare :is(.ph-rooms, .ph-teams, .dx-furn, .dx-nbfill, .dx-lab, .dx-nb, .dx-fill) { display: none; }   /* .dx-fill: the fitted rooms' fills, cut round their furniture */\n"
        "/* drawn as the core & shell drawing draws it */\n"
        "#world-plan .dd-glaze { display: none; pointer-events: none; }\n"
        "#world-plan.bare .dd-glaze { display: block; }\n"
        "#world-plan .dd-glaze path { fill: none; stroke: #3fc1ea; stroke-width: 3; stroke-linejoin: round; stroke-linecap: round; vector-effect: non-scaling-stroke; }\n"
        "#world-plan.bare .pl-dd path { stroke-width: 1; fill-opacity: .78; }\n"
        "#world-plan.bare .pl-dd [data-k=\"lift\"] { fill: #cfcfcf; stroke: #9a9a9a; }\n"
        "#world-plan.bare .pl-dd [data-k=\"stair\"] { fill: #8e8e8e; stroke: #6f6f6f; }\n"
        "#world-plan.bare .pl-dd [data-k=\"wash\"] { fill: #cfe0f6; stroke: #a9c4e8; }\n"
        "#world-plan.bare .pl-dd [data-k=\"ahu\"] { fill: #b5d1e4; stroke: #8fb3cc; }\n"
        "#world-plan.bare .pl-dd [data-k=\"slab\"] { fill: url(#dd-hatch); fill-opacity: 1; stroke: #3a9a46; stroke-width: 2; stroke-dasharray: none; }\n"
        "#s-layout-dd .dd-key { display: flex; gap: calc(var(--pt) * 10); margin-top: calc(var(--pt) * 4); font-size: calc(var(--pt) * 6.6); color: #555; }\n"
        "#s-layout-dd .dd-key span { display: inline-flex; align-items: center; gap: calc(var(--pt) * 3); }\n"
        "#s-layout-dd .dd-key i.g { display: inline-block; width: calc(var(--pt) * 12); border-top: 2px solid #3fc1ea; }\n"
        "#s-layout-dd .dd-key i.e { display: inline-block; width: 0; height: 0; border-left: calc(var(--pt) * 3.5) solid transparent; border-right: calc(var(--pt) * 3.5) solid transparent; border-top: calc(var(--pt) * 5) solid #c40000; }\n"
        "</style>", "css")
    wr(p, s, nl)
print("ok ddshell")
